import * as THREE from 'three/webgpu';
import { texture as texNode } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Load sprite texture (cached by ctx.textureLoader)
  const textureUrl = config.assets?.imageUrl || '/prism-mock/home/nodes/floating-accent.png';
  const spriteTexture = ctx.textureLoader.load(textureUrl);

  // Plane geometry sized to atlas aspect ratio (512×320 = 1.6:1)
  const atlasAspect = 512 / 320;
  const planeHeight = 1.2;
  const planeWidth = planeHeight * atlasAspect;
  const geometry = new THREE.PlaneGeometry(planeWidth, planeHeight);

  // TSL-based material with texture node
  const material = new THREE.MeshBasicNodeMaterial({
    colorNode: texNode(spriteTexture),
  });

  const planeMesh = new THREE.Mesh(geometry, material);
  group.add(planeMesh);

  // Add MSDF text label
  const textContent = config.textContent?.text || 'Collection 1';
  const textMesh = ctx.fontAtlas.createText(textContent, {
    fontSize: 0.34,
    font: 'Lora',
    weight: 400,
    align: 'center',
  });
  textMesh.position.z = 0.01;
  group.add(textMesh);

  // Resource cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    spriteTexture.dispose();
  };

  // No event handlers for static element
  group.userData.handlers = {};

  return group;
}
